UPDATE dbo.product_price SET Price=900 WHERE ProductID=1; UPDATE dbo.product_price SET Price=Price+100 WHERE ProductID IN(2,3,4); BEGIN TRY UPDATE dbo.product_price SET Price=400 WHERE ProductID=1; END TRY BEGIN CATCH SELECT ERROR_MESSAGE() ExpectedError; END CATCH; BEGIN TRY UPDATE dbo.product_price SET Price=CASE WHEN ProductID=2 THEN 200 ELSE Price+50 END WHERE ProductID IN(2,5); END TRY BEGIN CATCH SELECT ERROR_MESSAGE() ExpectedBatchError; END CATCH; SELECT * FROM dbo.product_price; SELECT * FROM dbo.price_audit ORDER BY AuditID; SELECT * FROM dbo.price_rejection_log ORDER BY RejectID;